def move_one_ball(arr):
    if not arr:
        return True
    n = len(arr)
    if n == 1:
        return True

    # Count the number of indices i where arr[i] > arr[i+1]
    # For a rotation of a sorted array, there should be at most 1 such "drop"
    drops = 0
    for i in range(n - 1):
        if arr[i] > arr[i + 1]:
            drops += 1

    # If there are no drops, the array is already sorted
    if drops == 0:
        return True

    # If there is exactly 1 drop, check if the last element is smaller than the first
    # This would allow one rotation to sort the array
    if drops == 1:
        # Find where the drop is
        for i in range(n - 1):
            if arr[i] > arr[i + 1]:
                # Check if rotating would work: arr[i+1] <= arr[0] and all elements in order
                # Actually, if there's exactly one drop and the array is otherwise sorted,
                # and arr[-1] < arr[0], then it works
                return arr[-1] < arr[0]
        return False

    # More than 1 drop means it's not a rotation of a sorted array
    return False

